'use strict';

/**
* Sort a double-precision floating-point strided array in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
*
* @module @stdlib/lapack/base/dlasrt
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasrt = require( '@stdlib/lapack/base/dlasrt' );
*
* var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
*
* dlasrt( 'increasing', 5, D );
* // D => <Float64Array>[ 3.0, 5.0, 7.0, 9.0, 11.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasrt = require( '@stdlib/lapack/base/dlasrt' );
*
* var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
* var stack = new Float64Array( 64 );
*
* dlasrt.ndarray( 'I', 5, D, 1, 0, stack, 1, 0 );
* // D => <Float64Array>[ 3.0, 5.0, 7.0, 9.0, 11.0 ]
*/


// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlasrt;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlasrt = main;
} else {
	dlasrt = tmp;
}


// EXPORTS //

module.exports = dlasrt;

// exports: { "ndarray": "dlasrt.ndarray" }
